import json
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import parse_bound


def _normalization_report(values):
    """Return the values used for comparison, including the naive policy."""
    report = {
        "comparison": "UTC",
        "default_timezone": DEFAULT_TIMEZONE.tzname(None),
        "naive_policy": MISSING_TZ_POLICY,
        "start_utc": values["start"].astimezone(DEFAULT_TIMEZONE).isoformat(),
    }
    if "end" in values:
        report["end_utc"] = values["end"].astimezone(DEFAULT_TIMEZONE).isoformat()
    return report


def _rejection(param, error, payload, normalized=None):
    rejection = build_rejection(param, error, payload)
    if normalized is not None:
        rejection["normalized"] = normalized
    return rejection


def validate_range(payload):
    values = {}
    errors = []

    for param in ("start_date", "end_date"):
        if param not in payload:
            if param == "start_date":
                errors.append(_rejection(param, "is required", payload))
            continue
        try:
            values["start" if param == "start_date" else "end"] = parse_bound(payload[param])
        except (TypeError, ValueError) as exc:
            errors.append(_rejection(param, f"invalid ISO 8601 timestamp: {exc}", payload))

    # end_date is optional, and a start-only query has no range to compare.
    if errors or "end" not in values:
        return errors

    start = values["start"]
    end = values["end"]
    normalized = _normalization_report(values)
    start_utc = start.astimezone(DEFAULT_TIMEZONE)
    end_utc = end.astimezone(DEFAULT_TIMEZONE)

    if end_utc < start_utc:
        errors.append(
            _rejection(
                "date_range",
                "end must not be before start after UTC normalization",
                payload,
                normalized,
            )
        )

    # During a fall-back overlap, the repeated local hour is ambiguous.  The
    # API rejects the specific shape where the offsets differ and the local
    # end clock moves backwards, even if UTC ordering is otherwise valid.
    same_local_date = start.date() == end.date()
    same_local_hour = start.hour == end.hour
    different_offsets = start.utcoffset() != end.utcoffset()
    local_clock_moves_back = end.timetz().replace(tzinfo=None) < start.timetz().replace(tzinfo=None)
    if same_local_date and same_local_hour and different_offsets and local_clock_moves_back:
        errors.append(
            _rejection(
                "date_range",
                "ambiguous fall-back DST range: local end clock is earlier than local start clock",
                payload,
                normalized,
            )
        )

    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

